#include <QCoreApplication>
#include <QMap>
#include <QSettings>
#include <QTemporaryDir>
#include <iostream>
namespace decodium {void beginActiveSettingsProfile(QSettings&) {}}
class DecodiumBridge{public:
 int m_nfa=200,m_nfb=3000,m_ndepth=1,m_qsoProgress=0,threadLimit=24,notifications=0;bool m_singleDecode=false,m_deepSearchEnabled=false,m_ft8ApEnabled=false,m_lowCpuModeEnabled=false,m_avgDecodeEnabled=false,latency=false,adaptive=false,pressure=false,severe=false;QString m_mode="FT8";QMap<QString,QVariant> legacy;
 void nfaChanged(){++notifications;}void nfbChanged(){++notifications;}void ndepthChanged(){++notifications;}void singleDecodeChanged(){++notifications;}void settingValueChanged(const QString&,const QVariant&){}void syncSettingToLegacyIni(const QString&k,const QVariant&v){legacy[k]=v;}int effectiveFtThreadLimit()const{return threadLimit;}bool ft4LatencyGuardActive()const{return latency;}bool ft4AdaptiveCpuLimitActive()const{return adaptive;}bool cpuPressureActive()const{return pressure;}bool cpuPressureSevereActive()const{return severe;}
 int nfa()const;void setNfa(int);int nfb()const;void setNfb(int);int ndepth()const;void setNdepth(int);bool singleDecode()const;void setSingleDecode(bool);int effectiveFt4ThreadLimit()const;int effectiveFt4DecodeDepth(int)const;int effectiveDecodeDepth()const;int legacyCompatibleDecodeDepthBits()const;int legacyDecodeQsoProgress()const;int legacyDecodeCqHint()const;
};
#include "bridge_refactor_decode_depth.inc"
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir dir;QSettings::setPath(QSettings::IniFormat,QSettings::UserScope,dir.path());auto check=[](bool ok,const char*n){if(!ok){std::cerr<<n<<" failed\n";std::exit(1);}std::cout<<n<<'\n';};DecodiumBridge b;b.setNfa(300);b.setNfb(2900);check(b.nfa()==300&&b.nfb()==2900,"frequencies");b.setNdepth(8);check(b.ndepth()==4&&b.legacy.value("NDepth").toInt()==3,"depth-clamp-legacy");b.setSingleDecode(true);QSettings s(QSettings::IniFormat,QSettings::UserScope,"Decodium","Decodium3");check(b.singleDecode()&&s.value("SingleDecode").toBool()&&s.value("ndepth").toInt()==4,"persist");int n=b.notifications;b.setSingleDecode(true);b.setNdepth(4);check(b.notifications==n,"no-duplicate");b.m_mode="FT4";check(b.effectiveDecodeDepth()==3&&b.effectiveFt4DecodeDepth(4)==3,"ft4-default");b.m_deepSearchEnabled=true;b.m_ft8ApEnabled=true;check(b.effectiveDecodeDepth()==4&&b.effectiveFt4DecodeDepth(4)==4&&b.legacyCompatibleDecodeDepthBits()==35,"deep-legacy");b.latency=true;check(b.effectiveFt4ThreadLimit()==4&&b.effectiveFt4DecodeDepth(4)==2,"latency-guard");b.latency=false;b.m_lowCpuModeEnabled=true;check(b.effectiveDecodeDepth()==2&&b.legacyCompatibleDecodeDepthBits()==2,"low-cpu");b.m_qsoProgress=9;check(b.legacyDecodeQsoProgress()==6&&b.legacyDecodeCqHint()==0,"legacy-hints");}
